# Prepare CSV readers and detect fields

def detect_fields(csv_path):
    with open(csv_path, 'r', newline='', encoding='utf-8-sig') as f:
        reader = csv.DictReader(f)
        fields = reader.fieldnames or []
    lower = {k.lower().strip(): k for k in fields}
    x = None; y = None; z = None
    for cand in ['e', 'east', 'easting', 'x']:
        for lk, orig in lower.items():
            if lk == cand or cand in lk:
                x = orig; break
        if x: break
    for cand in ['n', 'north', 'northing', 'y']:
        for lk, orig in lower.items():
            if lk == cand or cand in lk:
                y = orig; break
        if y: break
    for cand in ['z', 'elev', 'elevation', 'level', 'rl']:
        for lk, orig in lower.items():
            if lk == cand or cand in lk:
                z = orig; break
        if z: break
    return fields, x, y, z

