# Create point FCs manually from CSV

def create_points(csv_path, fc_name, x_field, y_field, z_field):
    fc = os.path.join(gdb, fc_name)
    if arcpy.Exists(fc):
        arcpy.management.Delete(fc)
    arcpy.management.CreateFeatureclass(gdb, fc_name, 'POINT', spatial_reference=sr, has_z='ENABLED')
    arcpy.management.AddField(fc, 'ZVAL', 'DOUBLE')
    inserted = 0
    with open(csv_path, 'r', newline='', encoding='utf-8-sig') as f, \
         arcpy.da.InsertCursor(fc, ['SHAPE@XYZ', 'ZVAL']) as ic:
        reader = csv.DictReader(f)
        for row in reader:
            try:
                x = float(str(row[x_field]).replace(',', '').strip())
                y = float(str(row[y_field]).replace(',', '').strip())
                z = float(str(row[z_field]).replace(',', '').strip())
            except Exception:
                continue
            ic.insertRow(((x, y, z), z))
            inserted += 1
    return fc, inserted

