# Cell size from boundary extent ~ reasonable dense grid
ext = arcpy.Describe(boundary_single).extent
width = max(ext.width, 1.0)
height = max(ext.height, 1.0)
cell = max(min(width, height) / 100.0, 0.5)
arcpy.env.extent = boundary_single
